<template>
  <view class="page">
    <view v-if="detail" class="card"><view class="row"><text>{{ title }}</text><text class="status">{{ statusText(detail.statusText, detail.status) }}</text></view><text>单号：{{ no }}</text><text>申请人：{{ detail.applicantName || '用户不存在' }}<text v-if="detail.applicantPhone"> / {{ detail.applicantPhone }}</text></text><text>金额：{{ detail.totalAmount || 0 }}</text><text>付款状态：{{ payStatusText(detail.payStatusText, detail.payStatus) }}</text><text>审核状态：{{ auditStatusText(detail.auditStatusText, detail.auditStatus) }}</text><text>入库状态：{{ receiveStatusText(detail.receiveStatusText, detail.receiveStatus) }}</text><text v-if="detail.rejectReason" class="warn">驳回原因：{{detail.rejectReason}}</text></view>
    <view class="card"><view class="section">商品明细</view><view v-for="item in items" :key="item.id" class="line"><text>{{item.productName || '商品已删除'}}{{ (item.skuText || item.skuName) ? ' / ' + (item.skuText || item.skuName) : ' / SKU 已删除' }}</text><text>x{{item.quantity}}</text></view></view>
    <view v-if="canVoucher" class="card"><view class="section">付款凭证</view><payment-voucher-upload v-model="voucherUrl"/><button type="primary" @click="submitVoucher">提交凭证</button></view>
    <view v-if="vouchers.length" class="card"><view class="section">历史凭证</view><view v-for="v in vouchers" :key="v.id" class="voucher-row"><image :src="v.voucherUrl" @click="preview(v.voucherUrl)"/><view><text>{{v.voucherNo}} / {{auditStatusText(v.voucherStatusText || v.auditStatusText, v.auditStatus)}}</text><text v-if="v.rejectReason" class="warn">{{v.rejectReason}}</text></view></view></view>
    <view v-if="mode==='handleTransfer'" class="card"><button v-if="detail.status==='SUBMITTED'" type="primary" @click="audit(true)">审核通过</button><button v-if="detail.status==='SUBMITTED'" @click="audit(false)">审核驳回</button><button v-if="detail.status==='PAYMENT_SUBMITTED'" type="primary" @click="payment(true)">确认付款</button><button v-if="detail.status==='PAYMENT_SUBMITTED'" @click="payment(false)">驳回付款</button><button v-if="detail.status==='PAYMENT_APPROVED'" type="primary" @click="dispatch">确认拨货</button><button v-if="canClose" @click="close">关闭调拨</button></view>
    <view v-if="canCancel" class="card"><button @click="cancelBusiness">取消申请</button></view>
    <view v-if="canReturn" class="card"><view class="section">售后退回</view><text>该调拨已完成入库，可按实际剩余库存申请退回所属区县代。</text><button @click="applyReturn">申请调拨退回</button></view>
    <view v-if="canReceive" class="card"><button type="primary" @click="receive">确认收货入库</button></view>
  </view>
</template>
<script>
import paymentVoucherUpload from '@/components/jk/payment-voucher-upload.vue';
import {getJkPlatformOrderDetail,getJkStockTransferDetail,getJkHandledTransferDetail,submitJkPlatformOrderVoucher,submitJkStockTransferVoucher,receiveJkPlatformOrder,receiveJkStockTransfer,auditJkHandledTransfer,confirmJkHandledTransferPayment,confirmJkHandledTransfer,closeJkHandledTransfer,cancelJkPlatformOrder,cancelJkStockTransfer} from '@/api/jk.js';
import { jkAuditStatusText, jkBusinessStatusText, jkPayStatusText, jkReceiveStatusText } from '@/utils/jk-display.js';
export default {components:{paymentVoucherUpload},data(){return{mode:'order',id:0,detail:null,items:[],vouchers:[],voucherUrl:''}},computed:{title(){return this.mode==='handleTransfer'?'下级调拨处理':this.mode==='transfer'?'我的调拨':'区县代订货'},no(){return this.mode==='order'?this.detail.platformOrderNo:this.detail.transferNo},canVoucher(){return this.mode!=='handleTransfer'&&this.detail&&['CREATED','AUDIT_APPROVED','PAYMENT_REJECTED'].indexOf(this.detail.status)!==-1},canReceive(){return this.detail&&((this.mode==='order'&&this.detail.status==='SHIPPED')||(this.mode==='transfer'&&this.detail.status==='TRANSFERRED'))},canClose(){return this.detail&&['SUBMITTED','AUDIT_APPROVED','PAYMENT_REJECTED'].indexOf(this.detail.status)!==-1},canCancel(){return this.detail&&this.mode!=='handleTransfer'&&((this.mode==='order'&&['CREATED','PAYMENT_REJECTED'].includes(this.detail.status))||(this.mode==='transfer'&&['SUBMITTED','AUDIT_REJECTED','PAYMENT_REJECTED'].includes(this.detail.status)))},canReturn(){return this.detail&&this.mode==='transfer'&&this.detail.status==='STOCK_IN'}},onLoad(q){this.mode=q.mode||'order';this.id=Number(q.id);if(['order','transfer','handleTransfer'].indexOf(this.mode)<0)return this.$util.Tips({title:'无效业务类型'});this.load()},onShow(){if(this.id)this.load()},methods:{statusText(text,status){if(text)return text;return jkBusinessStatusText(status)},payStatusText(text,status){if(text)return text;return jkPayStatusText(status)},auditStatusText(text,status){if(text)return text;return jkAuditStatusText(status)},receiveStatusText(text,status){if(text)return text;return jkReceiveStatusText(status)},load(){let f=this.mode==='handleTransfer'?getJkHandledTransferDetail:(this.mode==='transfer'?getJkStockTransferDetail:getJkPlatformOrderDetail);f(this.id).then(r=>{let p=r.data||r;this.detail=this.mode==='order'?p.order:p.transfer;this.items=p.items||[];this.vouchers=p.vouchers||[]})},submitVoucher(){if(!this.voucherUrl)return this.$util.Tips({title:'请上传付款凭证'});(this.mode==='order'?submitJkPlatformOrderVoucher:submitJkStockTransferVoucher)(this.id,{voucherUrl:this.voucherUrl}).then(()=>{this.voucherUrl='';this.load()})},audit(approved){auditJkHandledTransfer({businessId:this.id,approved,remark:approved?'APP审核通过':'APP审核驳回'}).then(()=>this.load())},payment(approved){confirmJkHandledTransferPayment({businessId:this.id,approved,remark:approved?'APP确认付款':'APP驳回付款'}).then(()=>this.load())},dispatch(){confirmJkHandledTransfer({businessId:this.id,remark:'APP确认拨货'}).then(()=>this.load())},close(){closeJkHandledTransfer({businessId:this.id,remark:'APP关闭调拨'}).then(()=>this.load())},receive(){(this.mode==='order'?receiveJkPlatformOrder:receiveJkStockTransfer)(this.id,{remark:'APP确认收货'}).then(()=>this.load())},cancelBusiness(){uni.showModal({title:'取消申请',editable:true,placeholderText:'请输入取消原因',success:r=>{if(r.confirm)(this.mode==='order'?cancelJkPlatformOrder:cancelJkStockTransfer)(this.id,{businessId:this.id,remark:r.content||'申请人主动取消'}).then(()=>this.load())}})},applyReturn(){uni.navigateTo({url:'/pages/jk/return/create?transferId='+this.id})},preview(url){uni.previewImage({urls:[url],current:url})}}};
</script>
<style scoped>.page{min-height:100vh;padding:24rpx;background:#f3fbf8}.card{display:flex;flex-direction:column;gap:14rpx;margin-bottom:18rpx;padding:26rpx;border-radius:20rpx;background:#fff;color:#48655e;box-shadow:0 8rpx 24rpx rgba(31,122,91,.08)}.row,.line{display:flex;justify-content:space-between}.section{font-size:29rpx;font-weight:600;color:#1f7a5b}.status{color:#20a87b}.warn{color:#bc6a16}.voucher-row{display:flex;gap:16rpx;align-items:center}.voucher-row image{width:108rpx;height:108rpx;border-radius:12rpx}.voucher-row view{display:flex;flex-direction:column;gap:8rpx}button{margin:0}</style>
